import React, { useState, useEffect, useRef } from 'react';
import { useLanguage } from '../context/LanguageContext';
import '../styles/dialogues.css';

const DISPLAY_STYLES = {
  NONE: { display: 'none' },
  INLINE_FLEX: { display: 'inline-flex' }
};

const Dialogues = () => {
  const { language, nativeLanguage } = useLanguage();
  const [dialogues, setDialogues] = useState({});
  const [currentDialogue, setCurrentDialogue] = useState('morning_routine');
  const [currentDialogueFileName, setCurrentDialogueFileName] = useState('');
  const [allThemes, setAllThemes] = useState([]);
  const [visibleThemes, setVisibleThemes] = useState(4);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [currentPhraseIndex, setCurrentPhraseIndex] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);
  const [totalTime, setTotalTime] = useState(0);
  const [showTranslations, setShowTranslations] = useState(false);
  const [volume, setVolume] = useState(1);
  const [isMuted, setIsMuted] = useState(false);

  const currentAudioRef = useRef(null);
  const audioElementsRef = useRef([]);
  const progressIntervalRef = useRef(null);
  const sequentialIndexRef = useRef(0);

  // Filter themes by language
  const filterThemesByLanguage = (themes, currentLanguage) => {
    if (!themes || !Array.isArray(themes)) return [];

    return themes.filter(theme => {
      if (!theme.availableLanguages) return true;
      return theme.availableLanguages.includes(currentLanguage);
    });
  };

  // Load initial data
  useEffect(() => {
    const loadDialogueData = async () => {
      try {
        const response = await fetch('/data/data.json');
        const data = await response.json();

        if (data?.themes) {
          const filteredThemes = filterThemesByLanguage(data.themes, language || 'en');
          setAllThemes(filteredThemes);

          if (filteredThemes.length > 0 && filteredThemes[0].topics?.length > 0) {
            const firstTopic = filteredThemes[0].topics[0];
            setCurrentDialogue(firstTopic.id);
            await loadDialogue(firstTopic.id);
          }
        }
      } catch (error) {
        console.error('Error loading dialogue data:', error);
        const defaultThemes = [
          {
            id: 'daily_conversations',
            title: 'Daily Conversations',
            topics: [
              { id: 'morning_routine', title: 'Morning Routine' }
            ]
          }
        ];
        setAllThemes(defaultThemes);
        await loadDialogue('morning_routine');
      }
    };

    loadDialogueData();
  }, []);

  // Reload dialogue when language changes
  useEffect(() => {
    if (language && currentDialogue) {
      console.log(`🔄 Language changed to ${language}, reloading dialogue: ${currentDialogue}`);
      loadDialogue(currentDialogue);
    }
  }, [language]);

  // Update themes when language changes
  useEffect(() => {
    const loadThemesForLanguage = async () => {
      try {
        const response = await fetch('/data/data.json');
        const data = await response.json();

        if (data?.themes) {
          const filteredThemes = filterThemesByLanguage(data.themes, language || 'en');
          setAllThemes(filteredThemes);
        }
      } catch (error) {
        console.error('Error loading themes for language:', error);
      }
    };

    if (language) {
      loadThemesForLanguage();
    }
  }, [language]);

  // Update translations when native language changes
  useEffect(() => {
    if (nativeLanguage) {
      console.log(`🌍 Native language changed to ${nativeLanguage}, translations will update`);
    }
  }, [nativeLanguage]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (currentAudioRef.current) {
        currentAudioRef.current.pause();
        currentAudioRef.current = null;
      }
      if (progressIntervalRef.current) {
        clearInterval(progressIntervalRef.current);
      }
    };
  }, []);

  // Get available dialogue file
  const getAvailableDialogueFile = async (dialogueId, currentLanguage) => {
    try {
      const response = await fetch(`/dialogues/${currentLanguage}/`);
      const text = await response.text();

      if (response.ok) {
        const fileMatches = text.match(/href="([^"]+\.txt)"/g);

        if (fileMatches) {
          const availableFiles = fileMatches.map(match => 
            match.replace('href="', '').replace('.txt"', '')
          );

          if (availableFiles.includes(dialogueId)) {
            return dialogueId;
          }

          if (availableFiles.length > 0) {
            return availableFiles[0];
          }
        }
      }
    } catch (error) {
      console.error('Error checking available files:', error);
    }

    return dialogueId;
  };

  // Load dialogue function
  const loadDialogue = async (dialogueId) => {
    try {
      stopAllAudio();

      const currentLanguage = language || 'en';
      console.log(`🌐 Using language from context: ${currentLanguage}`);

      const actualFileName = await getAvailableDialogueFile(dialogueId, currentLanguage);
      setCurrentDialogueFileName(actualFileName);
      console.log(`📁 Using file: ${actualFileName}.txt for dialogue ${dialogueId}`);

      let response = await fetch(`/dialogues/${currentLanguage}/${actualFileName}.txt`);

      if (!response.ok) {
        console.warn(`Dialogue not found in ${currentLanguage}, trying English fallback`);
        if (currentLanguage !== 'en') {
          response = await fetch(`/dialogues/en/${actualFileName}.txt`);
        }

        if (!response.ok) {
          throw new Error(`Dialogue file not found: ${actualFileName}`);
        }
      }

      const content = await response.text();
      const parsedDialogue = parseDialogueTxt(content);

      if (parsedDialogue && parsedDialogue.lines && parsedDialogue.lines.length > 0) {
        setDialogues(prev => ({
          ...prev,
          [dialogueId]: parsedDialogue
        }));

        setCurrentPhraseIndex(0);
        setCurrentTime(0);

        const currentTheme = allThemes.find(theme => 
          theme.topics && theme.topics.some(topic => topic.id === dialogueId)
        );
        const audioFolder = currentTheme?.topics?.find(topic => topic.id === dialogueId)?.audioFolder || actualFileName || dialogueId;

        await preloadAudios(audioFolder, parsedDialogue);

        const totalDuration = parsedDialogue.lines.reduce((total, line) => {
          const wordCount = line.text.split(' ').length;
          return total + Math.max(2, wordCount * 0.5);
        }, 0);
        setTotalTime(totalDuration);

        return parsedDialogue;
      } else {
        throw new Error('Invalid dialogue format');
      }
    } catch (error) {
      console.error('Error loading dialogue:', error);
      return null;
    }
  };

  // Parse dialogue text
  const parseDialogueTxt = (content) => {
    const lines = content.split('\n');
    const dialogue = { title: '', lines: [] };
    let currentLine = {};

    for (const rawLine of lines) {
      const line = rawLine.trim();
      if (!line) {
        if (currentLine.speaker && currentLine.text) {
          dialogue.lines.push({ ...currentLine });
          currentLine = {};
        }
        continue;
      }

      if (line.startsWith('title:')) {
        dialogue.title = line.substring(6).trim();
      } else if (line.startsWith('speaker:')) {
        if (currentLine.speaker && currentLine.text) {
          dialogue.lines.push({ ...currentLine });
        }
        currentLine = {
          speaker: line.substring(8).trim(),
          text: '',
          translations: {}
        };
      } else if (line.startsWith('text:')) {
        currentLine.text = line.substring(5).trim();
      } else if (line.includes(':') && currentLine && !line.startsWith('title:') && !line.startsWith('speaker:') && !line.startsWith('text:')) {
        const [lang, translation] = line.split(':', 2);
        if (lang && translation && currentLine.translations) {
          currentLine.translations[lang.trim()] = translation.trim();
        }
      }
    }

    if (currentLine.speaker && currentLine.text) {
      dialogue.lines.push(currentLine);
    }

    return dialogue;
  };

  // Preload audios
  const preloadAudios = async (dialogueId, dialogue) => {
    audioElementsRef.current.forEach(audio => {
      if (audio && typeof audio.pause === 'function') {
        audio.pause();
        audio.src = '';
      }
    });
    audioElementsRef.current = [];

    const currentLanguage = language || 'en';
    console.log(`🎵 Preloading audios for language: ${currentLanguage}`);

    dialogue.lines.forEach((_, index) => {
      const audio = new Audio();
      const audioPath = `/audio/${currentLanguage}/${dialogueId}/line_${index}.mp3`;
      audio.src = audioPath;
      audio.preload = 'auto';
      audio.volume = isMuted ? 0 : volume;

      console.log(`🎵 Loading audio ${index}: ${audioPath}`);

      audio.addEventListener('canplaythrough', () => {
        console.log(`✅ Audio ${index} loaded successfully: ${audioPath}`);
      });

      audio.addEventListener('error', (e) => {
        console.warn(`⚠️ Failed to load audio ${index}:`, e);

        if (currentLanguage !== 'en') {
          const fallbackPath = `/audio/en/${dialogueId}/line_${index}.mp3`;
          audio.src = fallbackPath;
        }
      });

      audioElementsRef.current[index] = audio;
    });
  };

  // Control functions
  const pauseDialogue = () => {
    setIsPlaying(false);
    setIsPaused(true);
    if (currentAudioRef.current) {
      currentAudioRef.current.pause();
    }
  };

  const resumeDialogue = () => {
    if (isPaused && currentAudioRef.current) {
      setIsPlaying(true);
      setIsPaused(false);
      currentAudioRef.current.play();
    }
  };

  const stopDialogue = () => {
    setIsPlaying(false);
    setIsPaused(false);
    setCurrentPhraseIndex(0);
    setCurrentTime(0);
    if (currentAudioRef.current) {
      currentAudioRef.current.pause();
      currentAudioRef.current.currentTime = 0;
    }
    if (progressIntervalRef.current) {
      clearInterval(progressIntervalRef.current);
    }
  };

  const stopAllAudio = () => {
    setIsPlaying(false);
    setIsPaused(false);
    setCurrentPhraseIndex(0);
    audioElementsRef.current.forEach(audio => {
      if (audio && typeof audio.pause === 'function') {
        audio.pause();
        audio.currentTime = 0;
      }
    });
    currentAudioRef.current = null;
    if (progressIntervalRef.current) {
      clearInterval(progressIntervalRef.current);
    }
  };

  // Function to play entire dialogue in sequence (Play button)
  const playDialogue = () => {
    console.log("🎵 Play button clicked - Starting sequence mode");

    if (isPlaying) {
      pauseDialogue();
      return;
    }

    setIsPlaying(true);

    // Resume from pause if we have a current audio
    if (currentAudioRef.current && !currentAudioRef.current.paused) {
      console.log("▶️ Resuming from paused state");
      currentAudioRef.current.onended = () => {
        if (isPlaying) {
          const nextIndex = sequentialIndexRef.current + 1;
          sequentialIndexRef.current = nextIndex;
          playCurrentPhrase();
        }
      };
      currentAudioRef.current.play().catch(error => {
        console.error('❌ Audio playback failed:', error);
      });
      return;
    }

    // Start from the current phrase index
    console.log(`🎯 Starting sequence from phrase: ${currentPhraseIndex}`);
    sequentialIndexRef.current = currentPhraseIndex;
    playCurrentPhrase();
  };

  // Function to play current phrase in sequence
  const playCurrentPhrase = () => {
    const currentDialogueData = dialogues[currentDialogue];
    const indexToPlay = sequentialIndexRef.current;

    if (!isPlaying || !currentDialogueData || indexToPlay >= currentDialogueData.lines.length) {
      console.log("🛑 Stopping playback - end of dialogue or not in sequence mode");
      stopDialogue();
      return;
    }

    console.log(`🎯 Playing phrase in sequence: ${indexToPlay}`);

    // Update visual state to match current playing phrase
    setCurrentPhraseIndex(indexToPlay);

    // Use preloaded audio element
    const audio = audioElementsRef.current[indexToPlay];
    if (!audio || !audio.src) {
      console.log(`❌ No audio element for phrase ${indexToPlay}`);
      // Skip to next phrase in sequence
      sequentialIndexRef.current++;
      if (sequentialIndexRef.current < currentDialogueData.lines.length) {
        setTimeout(() => playCurrentPhrase(), 100);
      } else {
        stopDialogue();
      }
      return;
    }

    console.log(`▶️ Playing audio: ${audio.src}`);

    currentAudioRef.current = audio;
    audio.volume = isMuted ? 0 : volume;

    // Always reset time to play from beginning in sequence
    audio.currentTime = 0;

    // Set up sequential playback
    audio.onended = () => {
      if (isPlaying) {
        sequentialIndexRef.current++;
        if (sequentialIndexRef.current < currentDialogueData.lines.length) {
          playCurrentPhrase();
        } else {
          console.log("🏁 End of dialogue reached");
          stopDialogue();
        }
      }
    };

    const playPromise = audio.play();

    if (playPromise !== undefined) {
      playPromise.then(() => {
        // Audio playing successfully
      }).catch(error => {
        console.error('❌ Audio playback failed:', error);
        // Skip to next phrase even with error
        sequentialIndexRef.current++;
        if (isPlaying && sequentialIndexRef.current < currentDialogueData.lines.length) {
          playCurrentPhrase();
        }
      });
    }
  };

  // Function to play individual phrase (when clicking on a phrase)
  const playPhrase = (index) => {
    console.log(`🎵 Playing phrase: ${index} (Single phrase mode)`);

    stopAllAudio(); // Stop any ongoing playback

    // Single phrase mode - should not continue automatically
    setIsPlaying(false);
    setCurrentPhraseIndex(index);
    sequentialIndexRef.current = index; // Set for reference

    const currentDialogueData = dialogues[currentDialogue];
    if (!currentDialogueData || index >= currentDialogueData.lines.length) {
      console.error('❌ Phrase index out of range');
      return;
    }

    const audio = audioElementsRef.current[index];
    if (!audio || !audio.src) {
      console.error('❌ Audio not available for this phrase');
      return;
    }

    currentAudioRef.current = audio;
    audio.volume = isMuted ? 0 : volume;
    audio.currentTime = 0;

    const playPromise = audio.play();

    if (playPromise !== undefined) {
      playPromise.then(() => {
        // Single phrase mode - do NOT continue automatically
        audio.onended = () => {
          console.log("🎵 Single phrase playback finished. Ready for manual play.");
          setIsPlaying(false);
        };
      }).catch(error => {
        console.error('❌ Audio playback failed:', error);
      });
    }
  };

  // Utility functions
  const playSpecificPhrase = (phraseIndex) => {
    playPhrase(phraseIndex);
  };

  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const toggleTranslations = () => {
    setShowTranslations(!showTranslations);
  };

  const toggleMute = () => {
    setIsMuted(!isMuted);
    if (currentAudioRef.current) {
      currentAudioRef.current.volume = !isMuted ? 0 : volume;
    }
  };

  const handleVolumeChange = (e) => {
    const newVolume = parseFloat(e.target.value);
    setVolume(newVolume);
    if (currentAudioRef.current && !isMuted) {
      currentAudioRef.current.volume = newVolume;
    }
  };

  const loadMoreThemes = () => {
    setVisibleThemes(prev => Math.min(prev + 4, allThemes.length));
  };

  const showLessThemes = () => {
    setVisibleThemes(4);
  };

  // Get current dialogue data
  const dialogue = dialogues[currentDialogue];

  return (
    <div className="dialogues-container">
      <div className="dialogue-content">
        <div className="dialogue-messages">
          {dialogue?.lines?.map((line, index) => (
            <div
              key={index}
              className={`message message-${index % 2 === 0 ? 'other' : 'user'} ${
                index === currentPhraseIndex ? 'current-phrase' : ''
              }`}
              onClick={() => playSpecificPhrase(index)}
            >
              <div className="message-content">
                <div className="speaker-name">{line.speaker}</div>
                <div className="message-text">{line.text}</div>
                {showTranslations && (
                  <div className="translation">
                    {line.translations?.[nativeLanguage] || line.translations?.pt || line.translations?.en || 'Tradução não disponível'}
                  </div>
                )}
              </div>
            </div>
          )) || (
            <div className="message">
              <div className="message-text">Carregando diálogo...</div>
            </div>
          )}
        </div>

        <div className="player-controls">
          <button 
            id="play-btn"
            className="player-btn primary"
            onClick={playDialogue}
            style={!isPlaying ? DISPLAY_STYLES.INLINE_FLEX : DISPLAY_STYLES.NONE}
          >
            <i className="fas fa-play"></i>
          </button>

          <button 
            id="pause-btn"
            className="player-btn"
            onClick={pauseDialogue}
            style={isPlaying ? DISPLAY_STYLES.INLINE_FLEX : DISPLAY_STYLES.NONE}
          >
            <i className="fas fa-pause"></i>
          </button>

          <button 
            id="stop-btn"
            className="player-btn"
            onClick={stopDialogue}
          >
            <i className="fas fa-stop"></i>
          </button>

          <div className="progress-container">
            <span className="time-display">
              {formatTime(currentTime)} / {formatTime(totalTime)}
            </span>
          </div>

          <div className="volume-controls">
            <button onClick={toggleMute} className="volume-btn">
              <i className={`fas ${isMuted ? 'fa-volume-mute' : 'fa-volume-up'}`}></i>
            </button>
            <input
              type="range"
              min="0"
              max="1"
              step="0.1"
              value={volume}
              onChange={handleVolumeChange}
              className="volume-slider"
            />
          </div>

          <button onClick={toggleTranslations} className="translation-btn">
            <i className="fas fa-language"></i>
          </button>
        </div>
      </div>

      <div className="themes-sidebar">
        <div className="themes-container">
          {allThemes.slice(0, visibleThemes).map((theme, index) => (
            <div key={theme.id || index} className="theme-card">
              <h3 className="theme-title">{theme.title}</h3>
              {theme.topics && theme.topics.map(topic => (
                <button
                  key={topic.id}
                  className={`topic-btn ${currentDialogue === topic.id ? 'active' : ''}`}
                  onClick={() => {
                    stopAllAudio();
                    setCurrentDialogue(topic.id);
                    loadDialogue(topic.id);
                  }}
                >
                  {topic.title}
                </button>
              ))}
            </div>
          ))}

          {visibleThemes < allThemes.length && (
            <button onClick={loadMoreThemes} className="load-more-btn">
              <i className="fas fa-chevron-down"></i>
              Mostrar mais
            </button>
          )}

          {visibleThemes > 4 && (
            <button onClick={showLessThemes} className="show-less-btn">
              <i className="fas fa-chevron-up"></i>
              Mostrar menos
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dialogues;
